import{c as t,Q as a,j as s,m as r}from"./chunks/framework.BqPkuuVc.js";const g=JSON.parse('{"title":"Results","description":"","frontmatter":{},"headers":[],"relativePath":"user/after-the-event/results.md","filePath":"user/after-the-event/results.md"}'),o={name:"user/after-the-event/results.md"};function i(n,e,l,h,u,c){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers publishing results after (or during) the event.</p><p>How to view, sort, and share results.</p><blockquote><p><strong>Status:</strong> Stub — not yet written.</p></blockquote><h2 id="what-this-page-will-cover" tabindex="-1">What this page will cover <a class="header-anchor" href="#what-this-page-will-cover" aria-label="Permalink to &quot;What this page will cover&quot;">​</a></h2><ul><li>[ ] The <strong>Results</strong> view — what&#39;s shown per class</li><li>[ ] Sorting and filtering</li><li>[ ] Showing splits, behind-leader, per-leg times for relays</li><li>[ ] Marking a result as official</li><li>[ ] Publishing interim (live) results vs. final results</li><li>[ ] What to do about disputed results</li><li>[ ] Relay results and leg results</li><li>[ ] Publishing live / interim results while the event is still running</li><li>[ ] Prize-giving lists — generating winner lists per class for the awards ceremony</li></ul><h2 id="overall-results-for-a-multi-stage-event" tabindex="-1">Overall results for a multi-stage event <a class="header-anchor" href="#overall-results-for-a-multi-stage-event" aria-label="Permalink to &quot;Overall results for a multi-stage event&quot;">​</a></h2><p>A stage of a <a href="./../event-setup/multi-stage-events">multi-stage event</a> has its own results, read here exactly like any other event&#39;s. The <strong>combined</strong> result across the stages lives on the carnival&#39;s <strong>Standings</strong> tab, not here: open the group header on the Events page.</p><p>The standings show, per class, each competitor&#39;s position, their contribution from each stage, and their total. They update live as a stage runs, so the overall is correct within about half a second of a card being downloaded. A stage that didn&#39;t count is struck through with the reason, and a total that is still provisional carries <code>*</code>.</p><p>See <a href="./../event-setup/multi-stage-events#standings">Standings</a> for what the columns and statuses mean.</p><h2 id="the-overall-result-of-a-knock-out-competition" tabindex="-1">The overall result of a knock-out competition <a class="header-anchor" href="#the-overall-result-of-a-knock-out-competition" aria-label="Permalink to &quot;The overall result of a knock-out competition&quot;">​</a></h2><p>A <a href="./../event-setup/knock-out-competitions">knock-out competition</a> is decided by how far each competitor got, not by a total, so its overall result is a <strong>classification</strong> rather than standings. It lives on the competition&#39;s <strong>Classification</strong> tab.</p><p>Two differences from a carnival&#39;s standings are worth knowing: the classification <strong>does not refresh on its own</strong> — leave the tab and come back to it after a round has been downloaded — and it has <strong>no export</strong> yet. Each round&#39;s own results read and export here exactly like any other event&#39;s.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../reference/status-and-race-time">Status and race time rules</a></li><li><a href="./../event-setup/multi-stage-events">Multi-stage events</a> — overall standings across a carnival</li><li><a href="./../event-setup/knock-out-competitions">Knock-out competitions</a> — the classification across rounds</li><li><a href="./exports">Exporting data</a></li><li><a href="./../running-the-event/resolving-issues">Resolving issues on the day</a></li></ul>',15)])])}const p=t(o,[["render",i]]);export{g as __pageData,p as default};
